class Solution {
    int cost(int minutes,int seconds,int start,int move,int push) {
        if(minutes<0||minutes>99||seconds<0||seconds>99) return INT_MAX;
        string s=to_string(minutes*100+seconds);
        int ans=0,pos=start;
        for(char c:s) {
            int d=c-'0';if(pos!=d) ans+=move;
            ans+=push;pos=d;
        }
        return ans;
    }
public:
    int minCostSetTime(int startAt, int moveCost, int pushCost, int targetSeconds) {
        int ans=INT_MAX;
        for(int sec=0;sec<=99;++sec) if((targetSeconds-sec)%60==0) {
            int minutes=(targetSeconds-sec)/60;
            ans=min(ans,cost(minutes,sec,startAt,moveCost,pushCost));
        }
        return ans;
    }
};
